package spms.view;

import spms.components.*;
import spms.controller.ModuleController;
import spms.model.User;
import spms.theme.AppTheme;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.time.Year;
import java.util.*;
import java.util.List;

/** Reusable data workspace configured separately for each SPMS module view. */
public final class ModuleScreen extends JPanel {
    private final String view;private final ModuleController controller;private final User user;private final DefaultTableModel model=new DefaultTableModel(){@Override public boolean isCellEditable(int r,int c){return false;}};private final StyledDataTable table=new StyledDataTable(model);private final JTextField search=new JTextField();private final JLabel status=new JLabel(" ");
    public ModuleScreen(String view,ModuleController controller,User user){this.view=view;this.controller=controller;this.user=user;setOpaque(false);setLayout(new BorderLayout(0,12));add(toolbar(),BorderLayout.NORTH);SurfaceCard card=new SurfaceCard();card.setLayout(new BorderLayout(0,10));card.add(new JLabel(caption()),BorderLayout.NORTH);table.setDefaultRenderer(Object.class,(t,value,selected,focus,row,col)->value!=null&&Set.of("PRESENT","ABSENT","LEAVE","PENDING","APPROVED","REJECTED","DRAFT","PROCESSED","PAID","ACTIVE","INACTIVE").contains(value.toString())?new StatusBadge(value.toString(),selected):new DefaultTableCellRendererFallback().render(t,value,selected,focus,row,col));card.add(new JScrollPane(table),BorderLayout.CENTER);add(card,BorderLayout.CENTER);status.setForeground(AppTheme.MUTED);add(status,BorderLayout.SOUTH);refresh();}
    private JPanel toolbar(){JPanel panel=new SurfaceCard();panel.setLayout(new BorderLayout(8,0));JPanel left=new JPanel(new FlowLayout(FlowLayout.LEFT,6,0));left.setOpaque(false);search.setPreferredSize(new Dimension(230,36));search.setToolTipText("Search this view");SecondaryButton find=new SecondaryButton("Search");find.addActionListener(e->refresh());search.addActionListener(e->refresh());left.add(search);left.add(find);panel.add(left,BorderLayout.WEST);JPanel right=new JPanel(new FlowLayout(FlowLayout.RIGHT,5,0));right.setOpaque(false);SecondaryButton print=new SecondaryButton("Print");print.addActionListener(e->{try{table.print(JTable.PrintMode.FIT_WIDTH);}catch(Exception ex){error(ex);}});SecondaryButton export=new SecondaryButton("Export CSV");export.addActionListener(e->exportCsv());right.add(print);right.add(export);
        if(view.equals("employees")||view.equals("departments")||view.equals("users")||view.equals("performance")&& !isEmployee()||view.equals("attendance")||view.equals("leaves")&&isEmployee()||view.equals("payroll")&&!isEmployee()){PrimaryButton add=new PrimaryButton(view.equals("leaves")?"Apply for leave":"＋ Add");add.addActionListener(e->add());right.add(add);}
        if(Set.of("employees","departments","performance","users").contains(view)&&!isEmployee()){SecondaryButton edit=new SecondaryButton("Edit");edit.addActionListener(e->edit());right.add(edit);}
        if(Set.of("employees","departments","users").contains(view)&&!isEmployee()){SecondaryButton delete=new SecondaryButton(view.equals("users")?"Activate / Deactivate":"Delete");delete.addActionListener(e->delete());right.add(delete);}
        if(view.equals("leaves")&&!isEmployee()){PrimaryButton approve=new PrimaryButton("Approve");approve.addActionListener(e->decide(true));SecondaryButton reject=new SecondaryButton("Reject");reject.addActionListener(e->decide(false));right.add(approve);right.add(reject);}
        if(view.equals("payroll")&&!isEmployee()){SecondaryButton paid=new SecondaryButton("Mark paid");paid.addActionListener(e->safe(()->controller.markPaid(id())));SecondaryButton payslip=new SecondaryButton("Payslip");payslip.addActionListener(e->showDetails());right.add(payslip);right.add(paid);}else if(view.equals("payroll")){SecondaryButton payslip=new SecondaryButton("Payslip");payslip.addActionListener(e->showDetails());right.add(payslip);}
        if(view.equals("employees")){SecondaryButton profile=new SecondaryButton("Profile");profile.addActionListener(e->showDetails());right.add(profile);}panel.add(right,BorderLayout.EAST);return panel;}
    private String caption(){return switch(view){case "employees"->"Employee records, department, designation and contact details.";case "attendance"->"Attendance history and daily present, absent or leave status.";case "leaves"->"Leave applications move through Pending, Approved and Rejected.";case "payroll"->"Net salary = basic salary + allowances − deductions.";case "performance"->"Evaluation period, rating, evaluator remarks and history.";case "departments"->"Maintain department names and descriptions.";case "users"->"Manage account roles and activation status.";default->"Live records from SPMS_DB.";};}
    private void refresh(){try{List<Map<String,Object>> rows=controller.load(view,search.getText());model.setRowCount(0);model.setColumnCount(0);if(rows.isEmpty()){model.addColumn(view);model.addRow(new Object[]{"No records found. Adjust your search or add a record."});}else{rows.get(0).keySet().forEach(model::addColumn);for(Map<String,Object> row:rows)model.addRow(row.values().toArray());}status.setText(rows.size()+" record(s) · Updated "+java.time.LocalTime.now().withNano(0));}catch(Exception e){error(e);}}
    private void add(){if(view.equals("users")){addUser();return;}switch(view){case "employees"->form("Add employee",new String[]{"Employee ID","Name","Email","Phone","Department","Designation","Joining date (YYYY-MM-DD)","Monthly salary"},v->controller.addEmployee(v[0],v[1],v[2],v[3],v[4],v[5],v[6],v[7]));case "attendance"->form("Mark attendance",new String[]{"Employee ID", "Work date (YYYY-MM-DD)","Status: PRESENT / ABSENT / LEAVE"},v->controller.attendance(v[0],v[1],v[2]));case "leaves"->form("Apply for leave",new String[]{"Employee ID","From (YYYY-MM-DD)","To (YYYY-MM-DD)","Leave type","Reason"},v->controller.applyLeave(v[0],v[1],v[2],v[3],v[4]));case "payroll"->form("Generate monthly payroll",new String[]{"Employee ID","Month (YYYY-MM)","Allowances","Deductions"},v->controller.payroll(v[0],v[1],v[2],v[3]));case "performance"->form("Add evaluation",new String[]{"Employee ID","Period","Rating (1-5)","Remarks"},v->controller.addPerformance(v[0],v[1],v[2],v[3]));case "departments"->form("Add department",new String[]{"Department name","Description"},v->controller.department(v[0],v[1]));default->form("Add record",new String[]{"Employee ID","Period","Rating","Remarks"},v->controller.addPerformance(v[0],v[1],v[2],v[3]));}}
    private void addUser(){JTextField name=new JTextField();JPasswordField password=new JPasswordField();JComboBox<String> role=new JComboBox<>(new String[]{"ADMIN","HR_MANAGER","EMPLOYEE"});JTextField employee=new JTextField();JPanel form=new JPanel(new GridLayout(4,2,8,8));for(Object[] row:new Object[][]{{"Username",name},{"Password",password},{"Role",role},{"Employee ID (if Employee)",employee}}){form.add(new JLabel(String.valueOf(row[0])));form.add((Component)row[1]);}if(JOptionPane.showConfirmDialog(this,form,"Create account",JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE)!=JOptionPane.OK_OPTION){password.setText("");return;}char[] secret=password.getPassword();try{safe(()->controller.addUser(name.getText(),secret,String.valueOf(role.getSelectedItem()),employee.getText()));}finally{Arrays.fill(secret,'\0');password.setText("");}}
    private void edit(){int row=selected();if(row<0)return;String key=String.valueOf(model.getValueAt(row,0));switch(view){case "employees"->form("Edit employee",new String[]{"Name","Email","Phone","Department","Designation","Monthly salary"},new String[]{cell(row,1),cell(row,4),cell(row,5),cell(row,2),cell(row,3),cell(row,8)},v->controller.updateEmployee(key,v[0],v[1],v[2],v[3],v[4],v[5]));case "departments"->form("Edit department",new String[]{"Department name","Description"},new String[]{cell(row,1),cell(row,2)},v->controller.updateDepartment(key,v[0],v[1]));case "performance"->form("Edit evaluation",new String[]{"Period","Rating (1-5)","Remarks"},new String[]{cell(row,3),cell(row,4),cell(row,6)},v->controller.updatePerformance(key,v[0],v[1],v[2]));case "users"->form("Change user role",new String[]{"Role: ADMIN / HR_MANAGER / EMPLOYEE"},new String[]{cell(row,2)},v->controller.changeRole(key,v[0]));default->JOptionPane.showMessageDialog(this,"Choose a record that can be edited.");}}
    private void delete(){int row=selected();if(row<0)return;String key=String.valueOf(model.getValueAt(row,0));if(view.equals("users")){boolean active=Boolean.parseBoolean(String.valueOf(model.getValueAt(row,4)));safe(()->controller.toggleUser(key,!active));return;}if(JOptionPane.showConfirmDialog(this,"Delete the selected record? Related records may be removed.","Confirm deletion",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;safe(()->{if(view.equals("employees"))controller.deleteEmployee(key);else controller.deleteDepartment(key);});}
    private void decide(boolean approve){int row=selected();if(row<0)return;String note=JOptionPane.showInputDialog(this,"Decision note (optional)",approve?"Approved":"Please contact HR");if(note!=null)safe(()->controller.decideLeave(String.valueOf(model.getValueAt(row,0)),approve,note));}
    private void form(String title,String[] labels,java.util.function.Consumer<String[]> action){String[] defaults=new String[labels.length];for(int i=0;i<labels.length;i++)defaults[i]=defaultValue(labels[i]);form(title,labels,defaults,action);}
    private void form(String title,String[] labels,String[] defaults,java.util.function.Consumer<String[]> action){JPanel form=new JPanel(new GridLayout(labels.length,2,8,8));JTextField[] fields=new JTextField[labels.length];for(int i=0;i<labels.length;i++){form.add(new JLabel(labels[i]));fields[i]=new JTextField(defaults[i]);form.add(fields[i]);}if(JOptionPane.showConfirmDialog(this,form,title,JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE)!=JOptionPane.OK_OPTION)return;String[] values=Arrays.stream(fields).map(JTextField::getText).toArray(String[]::new);safe(()->action.accept(values));}
    private String cell(int row,int column){return column<model.getColumnCount()?Objects.toString(model.getValueAt(row,column),""):"";}
    private String defaultValue(String label){if(label.startsWith("Employee ID")&&isEmployee())return Objects.toString(user.employeeId(),"");if(label.startsWith("Work date"))return LocalDate.now().toString();if(label.startsWith("From "))return LocalDate.now().toString();if(label.startsWith("To "))return LocalDate.now().plusDays(1).toString();if(label.startsWith("Joining date"))return LocalDate.now().toString();if(label.startsWith("Month"))return LocalDate.now().format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM"));if(label.startsWith("Department"))return "Engineering";if(label.startsWith("Status"))return "PRESENT";if(label.startsWith("Leave type"))return "Annual";if(label.startsWith("Period"))return Year.now().getValue()+" H1";if(label.startsWith("Rating"))return "4.0";if(label.startsWith("Role"))return "EMPLOYEE";if(label.startsWith("Allowances")||label.startsWith("Deductions"))return "0";return "";}
    private void showDetails(){int row=selected();if(row<0)return;StringBuilder b=new StringBuilder();for(int c=0;c<model.getColumnCount();c++)b.append(model.getColumnName(c)).append(": ").append(model.getValueAt(row,c)).append('\n');JOptionPane.showMessageDialog(this,b.toString(),view.equals("payroll")?"SPMS · Payslip":"SPMS · Employee profile",JOptionPane.INFORMATION_MESSAGE);}
    private int selected(){int selected=table.getSelectedRow();if(selected<0){error(new IllegalArgumentException("Select a row first."));return -1;}return table.convertRowIndexToModel(selected);}
    private String id(){int row=selected();if(row<0)throw new IllegalArgumentException("Select a record first.");return String.valueOf(model.getValueAt(row,0));}
    private void safe(Runnable action){try{action.run();refresh();}catch(Exception e){error(e);}}
    private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage()==null?"The operation could not be completed.":e.getMessage(),"SPMS · Action needed",JOptionPane.ERROR_MESSAGE);}
    private boolean isEmployee(){return user.role().equals("EMPLOYEE");}
    private void exportCsv(){JFileChooser chooser=new JFileChooser();chooser.setSelectedFile(new File("spms-report.csv"));if(chooser.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;try(Writer w=new OutputStreamWriter(new FileOutputStream(chooser.getSelectedFile()),StandardCharsets.UTF_8)){for(int c=0;c<model.getColumnCount();c++){if(c>0)w.write(",");w.write(csv(model.getColumnName(c)));}w.write("\r\n");for(int r=0;r<model.getRowCount();r++){for(int c=0;c<model.getColumnCount();c++){if(c>0)w.write(",");w.write(csv(String.valueOf(model.getValueAt(r,c))));}w.write("\r\n");}}catch(IOException e){error(new IllegalArgumentException("Could not export the report."));}}
    private String csv(String s){return "\""+s.replace("\"","\"\"")+"\"";}
    private static final class DefaultTableCellRendererFallback extends JLabel{Component render(JTable t,Object v,boolean selected,boolean focus,int row,int column){setText(Objects.toString(v,""));setOpaque(true);setBackground(selected?t.getSelectionBackground():Color.WHITE);setForeground(selected?t.getSelectionForeground():AppTheme.INK);setBorder(new EmptyBorder(0,9,0,4));return this;}}
}
